package com.rooted.model;

import java.time.LocalDateTime;

/**
 * Represents a personal garden journal entry written by a member.
 * Maps to the `journals` table in the database.
 *
 * authorName and excerpt are computed fields:
 *  - authorName: populated by JournalDAO via JOIN with users table
 *  - excerpt:    first 200 chars of body, generated by getExcerpt()
 *    (not stored in DB — computed on the fly for listing pages)
 */
public class Journal {

    private static final int EXCERPT_LENGTH = 200;

    private int           id;
    private int           userId;
    private String        title;
    private String        body;
    private LocalDateTime createdAt;

    // Computed field — populated by DAO via JOIN, not stored in DB
    private String        authorName;    // username from users table

    // --- Constructors ---

    public Journal() {}

    /** Constructor used when creating a new journal entry (before DB insert). */
    public Journal(int userId, String title, String body) {
        this.userId = userId;
        this.title  = title;
        this.body   = body;
    }

    // --- Getters & Setters ---

    public int getId()                         { return id; }
    public void setId(int id)                  { this.id = id; }

    public int getUserId()                     { return userId; }
    public void setUserId(int userId)          { this.userId = userId; }

    public String getTitle()                   { return title; }
    public void setTitle(String title)         { this.title = title; }

    public String getBody()                    { return body; }
    public void setBody(String body)           { this.body = body; }

    public LocalDateTime getCreatedAt()                   { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt)     { this.createdAt = createdAt; }

    public String getAuthorName()                         { return authorName; }
    public void setAuthorName(String authorName)          { this.authorName = authorName; }

    /**
     * Returns a short preview of the journal body for listing pages.
     * Trims to EXCERPT_LENGTH characters and appends "..." if truncated.
     * Safe to call even if body is null.
     *
     * @return excerpt string, never null
     */
    public String getExcerpt() {
        if (body == null || body.isEmpty()) return "";
        if (body.length() <= EXCERPT_LENGTH)  return body;
        return body.substring(0, EXCERPT_LENGTH).trim() + "...";
    }

    @Override
    public String toString() {
        return "Journal{id=" + id + ", title='" + title + "', author='" + authorName + "'}";
    }
}
